// Temporary independent projection/replay probe, not production recovery.
#[test]
#[ignore]
fn two_layer_candidates_pass_real_rust_source_acceptance() {
    let cases: &[(usize, usize, &[&[usize]])] = &[
(6, 400185, &[&[2, 7], &[3, 2], &[4, 9], &[4], &[3, 11], &[], &[8, 7], &[9, 2], &[4, 9], &[10], &[9, 11], &[]]),
(6, 366684, &[&[3, 1], &[10, 2], &[7, 9], &[6, 10], &[2, 11], &[], &[3, 1], &[4, 2], &[7, 3], &[0, 4], &[2, 11], &[]]),
(6, 348064, &[&[3, 1], &[10, 8], &[4, 9], &[4], &[2, 11], &[], &[9, 7], &[10, 2], &[4, 3], &[4], &[8, 11], &[]]),
(7, 4930763, &[&[3, 1], &[11, 2], &[4, 10], &[2], &[10, 12], &[3], &[], &[10, 8], &[11, 2], &[4, 3], &[2], &[3, 5], &[10], &[]]),
(7, 6000828, &[&[11, 1], &[10, 9], &[3], &[8, 11], &[10, 5], &[4], &[], &[11, 8], &[3, 2], &[10], &[1, 11], &[3, 12], &[11], &[]]),
(7, 11144156, &[&[4, 1], &[5, 2], &[3, 3], &[11], &[2, 5], &[2, 13], &[], &[11, 8], &[5, 2], &[3, 10], &[11], &[9, 12], &[9, 13], &[]]),
(7, 12901869, &[&[5, 1], &[13, 9], &[5, 3], &[12, 4], &[3], &[4, 13], &[], &[12, 8], &[13, 9], &[5, 10], &[5, 4], &[10], &[4, 13], &[]]),
(7, 4906202, &[&[2, 8], &[5, 2], &[11, 10], &[12, 4], &[9, 12], &[3], &[], &[9, 8], &[12, 2], &[4, 3], &[12, 11], &[2, 12], &[3], &[]]),
(7, 10775771, &[&[10, 8], &[12, 2], &[4, 3], &[5], &[10], &[9, 13], &[], &[3, 8], &[12, 9], &[11, 3], &[12], &[3], &[9, 13], &[]]),
(7, 13221132, &[&[11, 8], &[9], &[12, 3], &[3, 11], &[1, 5], &[11, 13], &[], &[4, 1], &[2], &[5, 10], &[10, 11], &[1, 5], &[11, 13], &[]]),
(7, 5951706, &[&[9, 1], &[5, 9], &[3], &[12, 4], &[2, 12], &[4], &[], &[9, 8], &[5, 9], &[10], &[5, 4], &[2, 5], &[4], &[]]),
(7, 11133627, &[&[3, 8], &[3, 2], &[8], &[6, 11], &[8, 12], &[2, 6], &[], &[10, 1], &[10, 9], &[8], &[6, 4], &[8, 5], &[9, 13], &[]]),
(7, 11263438, &[&[13, 1], &[11, 9], &[5, 3], &[5, 11], &[10, 12], &[9, 6], &[], &[6, 8], &[11, 2], &[12, 10], &[12, 4], &[3, 5], &[9, 6], &[]]),
(7, 6004331, &[&[10, 8], &[12], &[6, 3], &[1, 4], &[3, 12], &[4], &[], &[10, 8], &[5], &[13, 3], &[8, 4], &[3, 12], &[4], &[]]),
(7, 11582701, &[&[12, 1], &[13, 9], &[4, 10], &[3, 4], &[5], &[3, 13], &[], &[12, 8], &[13, 9], &[4, 10], &[10, 4], &[12], &[10, 13], &[]]),
(7, 12231756, &[&[11, 1], &[10], &[3], &[2, 11], &[9, 5], &[10, 13], &[], &[11, 1], &[3], &[10], &[9, 4], &[2, 12], &[10, 13], &[]]),
    ];
    fn restore(nodes: &mut Vec<Node>, count: usize) {
        nodes.retain_mut(|node| match node {
            Node::Step { address, assignments } => {
                if *address % 2 == 1 {
                    assert!(assignments.is_empty());
                    false
                } else {
                    *address = (*address / 2) % count as u64;
                    true
                }
            }
            Node::If { taken, not_taken, .. } => {
                restore(taken, count);
                restore(not_taken, count);
                true
            }
            Node::Loop(body) => { restore(body, count); true }
            _ => true,
        });
    }
    fn counts(nodes: &[Node], result: &mut [usize]) {
        for node in nodes {
            match node {
                Node::Step { address, .. } => result[*address as usize] += 1,
                Node::If { taken, not_taken, .. } => { counts(taken, result); counts(not_taken, result); }
                Node::Loop(body) => counts(body, result),
                _ => {}
            }
        }
    }
    for &(count, graph, adjacency) in cases {
        assert_eq!(adjacency.len(), 2 * count);
        for profile in 0..3 {
            let source = larger_program(count, graph, profile);
            let mut instructions = Vec::new();
            for (node, targets) in adjacency.iter().enumerate() {
                let original = &source.instructions()[node % count];
                let address = (2 * node) as u64;
                let control = match &original.control {
                    Control::Branch { condition, target } => {
                        assert_eq!(targets.len(), 2);
                        assert_eq!(targets[0] % count, *target as usize);
                        assert_eq!(targets[1] % count, node % count + 1);
                        instructions.push(IrInstruction { address: address + 1, size: 1, assignments: vec![], control: Control::Jump((2 * targets[1]) as u64) });
                        Control::Branch { condition: condition.clone(), target: (2 * targets[0]) as u64 }
                    }
                    Control::Jump(target) => {
                        assert_eq!(targets.len(), 1);
                        assert_eq!(targets[0] % count, *target as usize);
                        Control::Jump((2 * targets[0]) as u64)
                    }
                    Control::Next => {
                        assert_eq!(targets.len(), 1);
                        assert_eq!(targets[0] % count, node % count + 1);
                        Control::Jump((2 * targets[0]) as u64)
                    }
                    Control::Return(value) => { assert!(targets.is_empty()); Control::Return(value.clone()) }
                };
                instructions.push(IrInstruction { address, size: 1, assignments: original.assignments.clone(), control });
            }
            instructions.sort_by_key(|i| i.address);
            let candidate = Program::new(0, 3, instructions).unwrap();
            let analysis = ControlFlowAnalysis::compute(candidate.cfg()).unwrap();
            assert!(analysis.is_reducible(), "{count} {graph}");
            let postdom = PostDominators::compute(candidate.cfg()).ok();
            let mut max_seen = 0;
            let mut source_rejected = 0;
            let mut accept = |mut function: StructuredFunction| {
                restore(&mut function.body, count);
                let mut copies = vec![0usize; count];
                counts(&function.body, &mut copies);
                max_seen = max_seen.max(*copies.iter().max().unwrap());
                if copies.iter().any(|&n| n > 2) { return None; }
                match structure_verify::validate(&source, &function.body) {
                    Ok(evidence) => function.evidence = evidence,
                    Err(_) => { source_rejected += 1; return None; }
                }
                Some(function)
            };
            let mut selected = None;
            let mut last_error = String::new();
            for limit in 1..=2 {
                match StructuredFunction::recover_reducible(&candidate, limit, 8192, &analysis, postdom.as_ref()) {
                    Ok(function) => selected = accept(function),
                    Err(error) => last_error = error.to_string(),
                }
                if selected.is_none() {
                    selected = StructuredFunction::recover_with_placement_candidates(&candidate, limit, 8192, &analysis, postdom.as_ref(), &mut accept);
                }
                if selected.is_some() { break; }
            }
            println!("PROBE n={count} graph={graph} profile={profile} accepted={} max_copies={max_seen} source_rejected={source_rejected} error={last_error:?}", selected.is_some());
            if let Some(function) = selected {
                compare_split_reports(&source, function.body(), &function);
            }
        }
    }
}
